class Solution {
public:
    int minimumDeleteSum(string s1, string s2) {
        int n = s2.size();
        vector<int> dp(n + 1, 0);
        for (int j = 1; j <= n; ++j) dp[j] = dp[j - 1] + s2[j - 1];
        for (char a : s1) {
            int previous = dp[0];
            dp[0] += a;
            for (int j = 1; j <= n; ++j) {
                int old = dp[j];
                if (a == s2[j - 1]) dp[j] = previous;
                else dp[j] = min(old + (int)a, dp[j - 1] + (int)s2[j - 1]);
                previous = old;
            }
        }
        return dp[n];
    }
};
